import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Swiper, SwiperSlide } from 'swiper/react';
import { FreeMode, Navigation, Thumbs, Keyboard, Mousewheel, A11y, Virtual } from 'swiper/modules';
import { useGallery } from '../../context/GalleryContext';
import { PhotoCard } from './PhotoCard';
import 'swiper/css';
import 'swiper/css/free-mode';
import 'swiper/css/navigation';
import 'swiper/css/thumbs';
import 'swiper/css/virtual';
import styles from './VerticalFlowView.module.css';

/**
 * Vertical View with virtualization for both main image and thumbnail sidebar.
 */
export function VerticalFlowView({ photos }) {
  const { toggleFavorite, toggleHidden, dispatch, photosArray, totalCount, loadPage } = useGallery();
  const [thumbsSwiper, setThumbsSwiper] = useState(null);
  const [hidingIds, setHidingIds] = useState(new Set());
  const [activeIndex, setActiveIndex] = useState(0);
  const [zoomLevel, setZoomLevel] = useState(1);
  const [isActualSize, setIsActualSize] = useState(false);
  const [panOrigin, setPanOrigin] = useState('50% 50%');
  const containerRef = useRef(null);

  // ... (keep the same zoom and pan handlers) ...
  const handleToggleHide = useCallback((id) => {
    setHidingIds(prev => new Set([...prev, id]));
    setTimeout(() => toggleHidden(id), 300);
  }, [toggleHidden]);

  const handleToggleFavorite = useCallback((id) => {
    toggleFavorite(id);
  }, [toggleFavorite]);

  const zoomIn = () => setZoomLevel(prev => Math.min(prev + 0.2, 5));
  const zoomOut = () => setZoomLevel(prev => Math.max(prev - 0.2, 0.1));
  const resetZoom = () => {
    setZoomLevel(1);
    setIsActualSize(false);
    setPanOrigin('50% 50%');
  };
  const setActualSize = () => {
    setIsActualSize(true);
    setZoomLevel(1);
    setPanOrigin('50% 50%');
  };

  const handleMouseMove = (e) => {
    if (zoomLevel <= 1 && !isActualSize) return;
    const container = containerRef.current;
    if (!container) return;

    const rect = container.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * 100;
    const y = ((e.clientY - rect.top) / rect.height) * 100;

    setPanOrigin(`${x}% ${y}%`);
  };

  useEffect(() => {
    const handleKeyDown = (e) => {
      const activePhoto = photosArray[activeIndex];
      if (!activePhoto) return;

      switch (e.key.toLowerCase()) {
        case 'n':
          handleToggleHide(activePhoto.id);
          break;
        case 't':
          handleToggleFavorite(activePhoto.id);
          break;
        case 'r':
          resetZoom();
          break;
        case 'a':
          setActualSize();
          break;
        case '+':
        case '=':
          zoomIn();
          break;
        case '-':
        case '_':
          zoomOut();
          break;
        default:
          break;
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [activeIndex, photosArray, handleToggleHide, handleToggleFavorite]);

  return (
    <div className={styles.verticalViewContainer}>
      {/* Immersive Floating Controls */}
      <button 
        className={styles.backToGridBtn}
        onClick={() => dispatch({ type: 'SET_VIEW_MODE', payload: 'GRID' })}
        aria-label="Back to Grid view"
        title="Exit Vertical View"
      >
        ⊞
      </button>

      {/* Main Image View (Left Area) */}
      <div className={styles.mainArea}>
        <Swiper
          onSlideChange={(swiper) => {
            setActiveIndex(swiper.activeIndex);
            resetZoom();
            loadPage(swiper.activeIndex);
            loadPage(swiper.activeIndex + 1);
          }}
          direction="vertical"
          spaceBetween={0}
          navigation={true}
          thumbs={{ swiper: thumbsSwiper && !thumbsSwiper.destroyed ? thumbsSwiper : null }}
          virtual
          modules={[FreeMode, Navigation, Thumbs, Keyboard, Mousewheel, A11y, Virtual]}
          className={styles.mainSwiper}
          keyboard={{ enabled: true, onlyInViewport: false }}
          mousewheel={true}
          centeredSlides={true}
        >
          {photosArray.map((photo, index) => (
            <SwiperSlide key={photo?.id || index} virtualIndex={index} className={styles.mainSlide}>
              {({ isActive }) => {
                if (!photo) return <div className={styles.mainPlaceholder}>Loading...</div>;
                return (
                <div className={`${styles.mainContent} ${isActive ? styles.activeMain : ''} ${hidingIds.has(photo.id) ? styles.hiding : ''}`}>
                  <div 
                    className={`${styles.imageFocusContainer} ${(zoomLevel > 1 || isActualSize) ? styles.panningActive : ''}`}
                    ref={isActive ? containerRef : null}
                    onMouseMove={isActive ? handleMouseMove : undefined}
                  >
                    <img 
                      src={photo.url} 
                      alt="Gallery focus view" 
                      className={`${styles.focusImage} ${isActualSize ? styles.actualSize : ''}`}
                      style={{ 
                        transform: !isActualSize ? `scale(${zoomLevel})` : undefined,
                        transformOrigin: panOrigin,
                        objectPosition: isActualSize ? panOrigin : '50% 50%',
                        transition: isActualSize ? 'none' : 'transform 0.2s ease-out, transform-origin 0.1s ease-out'
                      }}
                      loading="lazy"
                    />
                  </div>
                  <div className={styles.imageOverlay} />
                  
                  {isActive && (
                    <>
                      <button
                        onClick={(e) => { e.stopPropagation(); handleToggleFavorite(photo.id); }}
                        className={styles.floatingFavBtn}
                        aria-label={photo.is_favorite ? "Remove from favorites" : "Add to favorites"}
                        title={photo.is_favorite ? "Remove from favorites" : "Add to favorites (t)"}
                      >
                        {photo.is_favorite ? '♥' : '♡'}
                      </button>
                      <button
                        onClick={(e) => { e.stopPropagation(); handleToggleHide(photo.id); }}
                        className={styles.floatingHideBtn}
                        aria-label={photo.is_hidden ? "Unhide photo" : "Hide photo"}
                        title={photo.is_hidden ? "Unhide photo" : "Hide photo (n)"}
                      >
                        {photo.is_hidden ? '👁️' : '🚫'}
                      </button>
                      <div className={styles.zoomControls}>
                        <button onClick={zoomIn} title="Zoom In (+)">+</button>
                        <button onClick={zoomOut} title="Zoom Out (-)">-</button>
                        <button onClick={resetZoom} title="Fit to View (r)">⟄</button>
                        <button onClick={setActualSize} title="Actual Size (a)">1:1</button>
                      </div>
                    </>
                  )}
                </div>
              );}}
            </SwiperSlide>
          ))}
        </Swiper>
      </div>

      {/* Thumbnail Sidebar (Right Area) */}
      <div className={styles.sidebarArea}>
        <Swiper
          onSwiper={setThumbsSwiper}
          direction="vertical"
          spaceBetween={15}
          slidesPerView="auto"
          freeMode={true}
          watchSlidesProgress={true}
          virtual
          modules={[FreeMode, Navigation, Thumbs, Mousewheel, Virtual]}
          className={styles.thumbsSwiper}
          mousewheel={true}
        >
          {photosArray.map((photo, index) => (
            <SwiperSlide key={photo?.id || index} virtualIndex={index} className={styles.thumbSlide}>
              <div className={styles.thumbWrapper}>
                {photo ? (
                  <>
                    <img src={photo.url} alt="Thumbnail" className={styles.thumbImage} />
                    {photo.is_favorite && <span className={styles.thumbFavBadge}>★</span>}
                  </>
                ) : (
                  <div className={styles.thumbPlaceholder}>...</div>
                )}
              </div>
            </SwiperSlide>
          ))}
        </Swiper>
      </div>
    </div>
  );
}
