import { createPortal } from 'react-dom';
import { useRef, useEffect } from 'react';
import { useGallery } from '../../context/GalleryContext';
import { TagManager } from '../tags/TagManager';
import styles from './PhotoModal.module.css';

/**
 * Full detail photo editor rendered as a native <dialog> via React Portal.
 * Fulfills REQ-UI-MODAL: Metadata editing and state controls.
 * Uses native <dialog> for built-in focus trapping and ESC-to-close behaviour.
 * @param {{ photo: import('../../services/idbStorage').PhotoRecord, onClose: () => void }} props
 */
export function PhotoModal({ photo, onClose }) {
  const { toggleFavorite, toggleHidden, deletePhoto } = useGallery();
  const dialogRef = useRef(null);

  useEffect(() => {
    const dialog = dialogRef.current;
    // Opens native modal with focus trap
    dialog?.showModal();
    
    // Lock body scroll
    document.body.style.overflow = 'hidden';
    
    return () => {
      dialog?.close();
      document.body.style.overflow = '';
    };
  }, []);

  const handleToggleHidden = () => {
    toggleHidden(photo.id);
  };

  const handleDelete = () => {
    if (window.confirm('Permanently remove this photo from your gallery?')) {
      deletePhoto(photo.id);
      onClose();
    }
  };

  return createPortal(
    <dialog ref={dialogRef} className={styles.dialog} onClose={onClose} aria-labelledby={`modal-title-${photo.id}`}>
      <h2 id={`modal-title-${photo.id}`} className="sr-only">Photo Details</h2>
      <button onClick={onClose} className={styles.closeBtn} aria-label="Close">✕</button>
      <img 
        src={photo.url} 
        className={styles.largeImage} 
        alt="Full size gallery view" 
        onError={e => { e.currentTarget.src = '/placeholder.svg'; }} 
      />

      <div className={styles.meta}>
        <p className={styles.url}><small>{photo.url}</small></p>
        <TagManager photo={photo} />
      </div>

      <div className={styles.actions}>
        <button onClick={() => toggleFavorite(photo.id)}>
          {photo.is_favorite ? '★ Unfavorite' : '☆ Favorite'}
        </button>
        <button onClick={handleToggleHidden}>
          {photo.is_hidden ? '👁 Unhide' : '🙈 Hide'}
        </button>
        <button onClick={handleDelete} className={styles.deleteBtn}>🗑 Delete</button>
      </div>
    </dialog>,
    document.body
  );
}
