import { useGallery } from '../../context/GalleryContext';
import { GridView } from './GridView';
import { CoverFlowView } from './CoverFlowView';
import { VerticalFlowView } from './VerticalFlowView';
import styles from './GalleryLayout.module.css';

/**
 * Selects and renders the appropriate layout based on viewMode.
 * Fulfills REQ-UI-LAYOUT-TOGGLE: Dual-mode rendering, now with Vertical View.
 */
export function GalleryLayout() {
  const { photos, photosArray, viewMode, loading, error } = useGallery();

  if (loading && photos.totalCount === 0) return <div className={styles.loader}>Loading gallery...</div>;
  if (error) return <div className={styles.error}>Error: {error}</div>;
  if (photos.totalCount === 0) return (
    <div className={styles.emptyState}>
      <p>No photos found. Add some URLs or clear your filters.</p>
    </div>
  );

  const renderContent = () => {
    switch (viewMode) {
      case 'GRID':
        return <GridView photos={photosArray} />;
      case 'COVER_FLOW':
        return <CoverFlowView photos={photosArray} />;
      case 'VERTICAL_FLOW':
        return <VerticalFlowView photos={photosArray} />;
      default:
        return <GridView photos={photosArray} />;
    }
  };

  return <div className={styles.layoutContainer}>{renderContent()}</div>;
}
