import { useGallery } from '../../context/GalleryContext';
import { TagFilter } from '../tags/TagFilter';
import { AddPhotoButton } from './AddPhotoButton';
import styles from './Navbar.module.css';

/**
 * Top navigation bar with search, filter, view toggle, and add photo actions.
 * Fulfills REQ-UI-TOOLBAR: Primary user controls.
 */
export function Navbar() {
  const { filterOptions = {}, viewMode, dispatch } = useGallery();

  return (
    <header className={styles.navbar}>
      <h1 className={styles.logo}>PWA Gallery</h1>

      <input
        type="search"
        placeholder="Search by URL..."
        value={filterOptions.searchQuery || ''}
        onChange={e => dispatch({ type: 'SET_FILTER', payload: { searchQuery: e.target.value } })}
        className={styles.searchInput}
        aria-label="Search photos by URL"
      />

      <TagFilter />

      <div className={styles.visibilityToggle}>
        <span className={styles.visibilityLabel}>Show:</span>
        <select
          value={
            filterOptions.showHidden
              ? 'HIDDEN'
              : filterOptions.onlyFavorites
                ? 'FAVORITES'
                : 'ALL'
          }
          onChange={e => {
            const val = e.target.value;
            dispatch({
              type: 'SET_FILTER',
              payload: {
                showHidden: val === 'HIDDEN',
                onlyFavorites: val === 'FAVORITES'
              }
            });
          }}
          className={styles.visibilitySelect}
          aria-label="Filter photos visibility"
        >
          <option value="ALL">All Photos</option>
          <option value="FAVORITES">Favorites Only</option>
          <option value="HIDDEN">Hidden Only</option>
        </select>
      </div>

      <button
        className={styles.viewToggle}
        onClick={() => {
          const modes = ['GRID', 'COVER_FLOW', 'VERTICAL_FLOW'];
          const nextIndex = (modes.indexOf(viewMode) + 1) % modes.length;
          dispatch({ type: 'SET_VIEW_MODE', payload: modes[nextIndex] });
        }}
        aria-label="Switch gallery view mode"
      >
        {viewMode === 'GRID' && '⊞ Grid'}
        {viewMode === 'COVER_FLOW' && '⟳ Cover Flow'}
        {viewMode === 'VERTICAL_FLOW' && '⇳ Vertical Flow'}
      </button>

      <AddPhotoButton />
    </header>
  );
}
