/**
 * Normalizes a tag string: lowercased, trimmed, spaces replaced with hyphens.
 * Fulfills REQ-TAG-NORMALIZE: Consistent tag representation.
 * @param {string} raw
 * @returns {string}
 */
export function normalizeTag(raw) {
  return raw.toLowerCase().trim().replace(/\s+/g, '-');
}

/**
 * Derives the set of all unique tags across the entire photo collection.
 * Used by TagFilter to build the options list.
 * Fulfills REQ-TAG-FILTER: Tag-based photo filtering.
 * @param {PhotoRecord[]} photos
 * @returns {string[]}
 */
export function getAllUniqueTags(photos) {
  return Array.from(new Set(photos.flatMap(p => p.tags || []))).sort();
}
