import React, { createContext, useContext, useReducer, useEffect, useMemo, useCallback } from 'react';
import {
  getPhotosCount,
  getPhotosPage,
  updatePhoto,
  deletePhoto as dbDeletePhoto,
  addPhotos as dbAddPhotos,
  getUniqueTags
} from '../services/idbStorage';
import { galleryReducer } from './galleryReducer';
import { useToast } from './ToastContext';

const GalleryContext = createContext(null);

const initialState = {
  photos: { items: {}, cacheOrder: [], totalCount: 0 },
  availableTags: [],
  loading: false,
  error: null,
  viewMode: 'GRID',
  filterOptions: { tags: [], onlyFavorites: false, searchQuery: '', showHidden: false },
};

/**
 * GalleryProvider wraps the app, loads data on mount, and exposes helpers.
 * Refactored for 1M+ photo support via chunked pagination.
 */
export function GalleryProvider({ children }) {
  const [state, dispatch] = useReducer(galleryReducer, initialState);
  const { addToast } = useToast();

  const loadPage = useCallback(async (index, limit = 50) => {
    // If index is already loaded, skip
    if (state.photos.items[index]) return;

    try {
      const offset = Math.floor(index / limit) * limit;
      const items = await getPhotosPage(offset, limit, state.filterOptions);
      dispatch({ type: 'APPEND_PAGE', payload: { offset, items } });
    } catch (err) {
      console.error('Failed to load page:', err);
    }
  }, [state.photos.items, state.filterOptions]);

  // Handle total count and initial chunk on mount or filter change
  useEffect(() => {
    let isMounted = true;
    dispatch({ type: 'LOAD_START' });
    dispatch({ type: 'CLEAR_PHOTOS' });

    const init = async () => {
      try {
        const [count, tags] = await Promise.all([
          getPhotosCount(state.filterOptions),
          getUniqueTags()
        ]);
        if (!isMounted) return;
        dispatch({ type: 'SET_TOTAL_COUNT', payload: count });
        dispatch({ type: 'SET_TAGS', payload: tags });

        // Preload first page
        const firstPage = await getPhotosPage(0, 100, state.filterOptions);
        if (!isMounted) return;
        dispatch({ type: 'APPEND_PAGE', payload: { offset: 0, items: firstPage, totalCount: count } });
      } catch (e) {
        if (!isMounted) return;
        dispatch({ type: 'LOAD_ERROR', payload: e.message });
        addToast(`Failed to load gallery: ${e.message}`, 'error');
      }
    };

    init();
    return () => { isMounted = false; };
  }, [state.filterOptions, addToast]);

  // Helper to find a photo by ID in the cache
  const findPhoto = useCallback((id) => {
    return Object.values(state.photos?.items || {}).find(p => p.id === id);
  }, [state.photos?.items]);

  // Derived state: For 1M items, we just return the sparse object. 
  // Components will access items by index.
  const photosArray = useMemo(() => {
    // This provides a "view" for components that still expect an array,
    // but with nulls for missing data.
    const arr = new Array(state.photos?.totalCount || 0).fill(null);
    Object.entries(state.photos?.items || {}).forEach(([idx, item]) => {
      arr[idx] = item;
    });
    return arr;
  }, [state.photos?.items, state.photos?.totalCount]);

  // Optimistic dispatch → async DB write
  const toggleFavorite = useCallback(async (id) => {
    const photo = findPhoto(id);
    if (!photo) return;

    dispatch({ type: 'TOGGLE_FAVORITE', payload: id });
    try {
      await updatePhoto(id, { is_favorite: !photo.is_favorite });
    } catch (err) {
      dispatch({ type: 'TOGGLE_FAVORITE', payload: id });
      addToast('Failed to update favorite status.', 'error');
    }
  }, [findPhoto, addToast]);

  const toggleHidden = useCallback(async (id) => {
    const photo = findPhoto(id);
    if (!photo) return;

    dispatch({ type: 'TOGGLE_HIDDEN', payload: id });
    try {
      await updatePhoto(id, { is_hidden: !photo.is_hidden });
    } catch (err) {
      dispatch({ type: 'TOGGLE_HIDDEN', payload: id });
      addToast('Failed to update hidden status.', 'error');
    }
  }, [findPhoto, addToast]);

  const addPhotos = useCallback(async (urls) => {
    try {
      const inserted = await dbAddPhotos(urls);
      // Reset everything to sync
      const count = await getPhotosCount(state.filterOptions);
      dispatch({ type: 'CLEAR_PHOTOS' });
      dispatch({ type: 'SET_TOTAL_COUNT', payload: count });
      addToast(`Added ${inserted} photos.`, 'info');
    } catch (err) {
      addToast('Failed to add photos to storage.', 'error');
    }
  }, [state.filterOptions, addToast]);

  const deletePhoto = useCallback(async (id) => {
    const photo = findPhoto(id);
    if (!photo) return;

    dispatch({ type: 'DELETE_PHOTO', payload: id });
    try {
      await dbDeletePhoto(id);
      addToast('Photo deleted successfully.', 'info');
      // Refresh count/list
      const count = await getPhotosCount(state.filterOptions);
      dispatch({ type: 'SET_TOTAL_COUNT', payload: count });
    } catch (err) {
      addToast('Failed to delete photo.', 'error');
    }
  }, [findPhoto, state.filterOptions, addToast]);

  const updatePhotoContext = useCallback(async (id, updates) => {
    const photo = findPhoto(id);
    if (!photo) return;

    dispatch({ type: 'UPDATE_PHOTO', payload: { id, ...updates } });
    try {
      await updatePhoto(id, updates);
    } catch (err) {
      dispatch({ type: 'UPDATE_PHOTO', payload: photo });
      addToast('Failed to update photo properties.', 'error');
    }
  }, [findPhoto, addToast]);

  const setViewMode = useCallback((mode) => {
    dispatch({ type: 'SET_VIEW_MODE', payload: mode });
  }, []);

  const setFilter = useCallback((filter) => {
    dispatch({ type: 'SET_FILTER', payload: filter });
  }, []);

  const resetFilters = useCallback(() => {
    dispatch({ type: 'RESET_FILTERS' });
  }, []);

  const value = useMemo(() => ({
    ...state,
    totalCount: state.photos.totalCount, // Explicitly expose at top level
    photosArray, // compatibility
    loadPage,
    findPhoto,
    dispatch,
    toggleFavorite,
    toggleHidden,
    addPhotos,
    deletePhoto,
    updatePhoto: updatePhotoContext,
    setViewMode,
    setFilter,
    resetFilters
  }), [
    state,
    photosArray,
    loadPage,
    findPhoto,
    toggleFavorite,
    toggleHidden,
    addPhotos,
    deletePhoto,
    updatePhotoContext,
    setViewMode,
    setFilter,
    resetFilters
  ]);

  return <GalleryContext.Provider value={value}>{children}</GalleryContext.Provider>;
}

/** Hook for consuming context. Throws if used outside provider. */
export function useGallery() {
  const ctx = useContext(GalleryContext);
  if (!ctx) throw new Error('useGallery must be used within GalleryProvider');
  return ctx;
}
