const MAX_CACHE_SIZE = 2000;

export function galleryReducer(state, action) {
  switch (action.type) {
    case 'LOAD_START':
      return { ...state, loading: true, error: null };
    case 'SET_TAGS':
      return { ...state, availableTags: action.payload };
    case 'SET_TOTAL_COUNT':
      return { ...state, photos: { ...state.photos, totalCount: action.payload } };
    case 'APPEND_PAGE': {
      const newItems = { ...state.photos.items };
      let newCacheOrder = [...(state.photos.cacheOrder || [])];
      
      const startIndex = action.payload.offset;
      action.payload.items.forEach((item, i) => {
        const targetIndex = startIndex + i;
        if (!newItems[targetIndex]) {
          newCacheOrder.push(targetIndex);
        }
        newItems[targetIndex] = item;
      });

      // Strict LRU Eviction
      while (newCacheOrder.length > MAX_CACHE_SIZE) {
        const indexToEvict = newCacheOrder.shift();
        delete newItems[indexToEvict];
      }

      return { 
        ...state, 
        photos: { 
          ...state.photos, 
          items: newItems,
          cacheOrder: newCacheOrder,
          totalCount: action.payload.totalCount ?? state.photos.totalCount
        },
        loading: false 
      };
    }
    case 'CLEAR_PHOTOS':
      return { ...state, photos: { items: {}, cacheOrder: [], totalCount: 0 } };
    case 'SET_PHOTOS': {
      const itemsMap = {};
      const newCacheOrder = [];
      action.payload.forEach((p, i) => {
        itemsMap[i] = p;
        newCacheOrder.push(i);
      });
      return { 
        ...state, 
        photos: { items: itemsMap, cacheOrder: newCacheOrder, totalCount: action.payload.length }, 
        loading: false 
      };
    }
    case 'LOAD_ERROR':
      return { ...state, loading: false, error: action.payload };
    case 'DELETE_PHOTO':
      // Complex with sparse arrays: we might just need to clear and reload for consistency
      return { ...state, photos: { items: {}, totalCount: 0 } };
    case 'TOGGLE_FAVORITE':
      const updatedItemsFav = { ...state.photos.items };
      Object.keys(updatedItemsFav).forEach(idx => {
        if (updatedItemsFav[idx].id === action.payload) {
          updatedItemsFav[idx] = { ...updatedItemsFav[idx], is_favorite: !updatedItemsFav[idx].is_favorite };
        }
      });
      return { ...state, photos: { ...state.photos, items: updatedItemsFav } };
    case 'TOGGLE_HIDDEN':
      const updatedItemsHidden = { ...state.photos.items };
      Object.keys(updatedItemsHidden).forEach(idx => {
        if (updatedItemsHidden[idx].id === action.payload) {
          updatedItemsHidden[idx] = { ...updatedItemsHidden[idx], is_hidden: !updatedItemsHidden[idx].is_hidden };
        }
      });
      return { ...state, photos: { ...state.photos, items: updatedItemsHidden } };
    case 'UPDATE_PHOTO':
      const updatedItemsProp = { ...state.photos.items };
      Object.keys(updatedItemsProp).forEach(idx => {
        if (updatedItemsProp[idx].id === action.payload.id) {
          updatedItemsProp[idx] = { ...updatedItemsProp[idx], ...action.payload };
        }
      });
      return { ...state, photos: { ...state.photos, items: updatedItemsProp } };
    case 'SET_VIEW_MODE':
      return { ...state, viewMode: action.payload };
    case 'SET_FILTER':
      return { ...state, filterOptions: { ...state.filterOptions, ...action.payload } };
    case 'RESET_FILTERS':
      return {
        ...state,
        filterOptions: { tags: [], onlyFavorites: false, searchQuery: '', showHidden: false },
      };
    default:
      return state;
  }
}
