import { GalleryProvider, useGallery } from './context/GalleryContext';
import { ToastProvider } from './context/ToastContext';
import { Navbar } from './features/gallery/Navbar';
import { GalleryLayout } from './features/gallery/GalleryLayout';
import styles from './App.module.css';

/**
 * Root application shell.
 * Fulfills REQ-APP-SHELL: Top-level layout with context provider.
 */
function AppContent() {
  const { viewMode } = useGallery();
  const showNavbar = viewMode !== 'VERTICAL_FLOW';

  return (
    <div className={styles.appShell}>
      {showNavbar && <Navbar />}
      <main className={styles.mainContent}>
        <GalleryLayout />
      </main>
    </div>
  );
}

function App() {
  return (
    <ToastProvider>
      <GalleryProvider>
        <AppContent />
      </GalleryProvider>
    </ToastProvider>
  );
}

export default App;
