import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Swiper, SwiperSlide } from 'swiper/react';
import { EffectCoverflow, Keyboard, A11y, Navigation, Virtual } from 'swiper/modules';
import { useGallery } from '../../context/GalleryContext';
import { PhotoCard } from './PhotoCard';
import 'swiper/css';
import 'swiper/css/effect-coverflow';
import 'swiper/css/navigation';
import 'swiper/css/virtual';
import styles from './CoverFlowView.module.css';

/**
 * 3D Carousel view using Swiper.js Coverflow effect and Virtualization.
 * Fulfills REQ-UI-COVERFLOW with 1M record support.
 */
export function CoverFlowView({ photos }) {
  const { toggleFavorite, toggleHidden, photosArray, totalCount, loadPage } = useGallery();
  const [hidingIds, setHidingIds] = useState(new Set());
  const [activeIndex, setActiveIndex] = useState(0);
  const [zoomLevel, setZoomLevel] = useState(1);
  const [isActualSize, setIsActualSize] = useState(false);
  const [panOrigin, setPanOrigin] = useState('50% 50%');
  const containerRef = useRef(null);

  // ... (keep the same zoom and pan handlers) ...
  const handleToggleHide = useCallback((id) => {
    setHidingIds(prev => new Set([...prev, id]));
    setTimeout(() => toggleHidden(id), 300);
  }, [toggleHidden]);

  const handleToggleFavorite = useCallback((id) => {
    toggleFavorite(id);
  }, [toggleFavorite]);

  const zoomIn = () => setZoomLevel(prev => Math.min(prev + 0.2, 5));
  const zoomOut = () => setZoomLevel(prev => Math.max(prev - 0.2, 0.1));
  const resetZoom = () => {
    setZoomLevel(1);
    setIsActualSize(false);
    setPanOrigin('50% 50%');
  };
  const setActualSize = () => {
    setIsActualSize(true);
    setZoomLevel(1);
    setPanOrigin('50% 50%');
  };

  const handleMouseMove = (e) => {
    if (zoomLevel <= 1 && !isActualSize) return;
    const container = containerRef.current;
    if (!container) return;

    const rect = container.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * 100;
    const y = ((e.clientY - rect.top) / rect.height) * 100;

    setPanOrigin(`${x}% ${y}%`);
  };

  useEffect(() => {
    const handleKeyDown = (e) => {
      const activePhoto = photosArray[activeIndex];
      if (!activePhoto) return;

      switch (e.key.toLowerCase()) {
        case 'n':
          handleToggleHide(activePhoto.id);
          break;
        case 't':
          handleToggleFavorite(activePhoto.id);
          break;
        case 'r':
          resetZoom();
          break;
        case 'a':
          setActualSize();
          break;
        case '+':
        case '=':
          zoomIn();
          break;
        case '-':
        case '_':
          zoomOut();
          break;
        default:
          break;
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [activeIndex, photosArray, handleToggleHide, handleToggleFavorite]);

  return (
    <div className={styles.container}>
      <Swiper
        onSlideChange={(swiper) => {
          setActiveIndex(swiper.activeIndex);
          resetZoom();
          // Ensure surrounding pages are loaded
          loadPage(swiper.activeIndex);
          loadPage(swiper.activeIndex + 1);
          loadPage(swiper.activeIndex - 1);
        }}
        effect="coverflow"
        grabCursor={true}
        centeredSlides={true}
        slidesPerView="auto"
        navigation={true}
        coverflowEffect={{
          rotate: 50,
          stretch: 50,
          depth: 150,
          modifier: 1.5,
          slideShadows: true,
          scale: 0.9,
        }}
        watchSlidesProgress={true}
        keyboard={{ enabled: true, onlyInViewport: false }}
        virtual
        modules={[EffectCoverflow, Keyboard, Navigation, A11y, Virtual]}
        className={styles.swiper}
      >
        {photosArray.map((photo, index) => (
          <SwiperSlide key={photo?.id || index} virtualIndex={index} className={styles.slide}>
            {({ isActive }) => {
              if (!photo) return <div className={styles.placeholder}>Loading...</div>;
              return (
                <div className={`${styles.slideContent} ${isActive ? styles.activeSlide : ''} ${hidingIds.has(photo.id) ? styles.hiding : ''}`}>
                  <div 
                    className={`${styles.imageContainer} ${isActualSize ? styles.actualSizeContainer : ''} ${(zoomLevel > 1 || isActualSize) ? styles.panningActive : ''}`}
                    ref={isActive ? containerRef : null}
                    onMouseMove={isActive ? handleMouseMove : undefined}
                  >
                    <div 
                      className={styles.zoomWrapper}
                      style={{ 
                        transform: !isActualSize ? `scale(${zoomLevel})` : undefined,
                        transformOrigin: panOrigin,
                        transition: isActualSize ? 'none' : 'transform 0.2s ease-out, transform-origin 0.1s ease-out'
                      }}
                    >
                      <PhotoCard photo={photo} isCoverFlowMode panOrigin={isActualSize ? panOrigin : '50% 50%'} />
                    </div>
                  </div>

                  {isActive && (
                    <div className={styles.actionButtons}>
                      <button
                        onClick={(e) => { e.stopPropagation(); handleToggleFavorite(photo.id); }}
                        className={styles.fullWidthFavoriteBtn}
                        aria-label={photo.is_favorite ? "Remove from favorites" : "Add to favorites"}
                        title="Favorite (t)"
                      >
                        {photo.is_favorite ? '★ Unfav' : '☆ Fav'}
                      </button>
                      <button
                        onClick={(e) => { e.stopPropagation(); handleToggleHide(photo.id); }}
                        className={styles.fullWidthFavoriteBtn}
                        aria-label={photo.is_hidden ? "Unhide photo" : "Hide photo"}
                        title="Hide (n)"
                      >
                        {photo.is_hidden ? '👁️ Unhide' : '🚫 Hide'}
                      </button>
                      <div className={styles.zoomControls}>
                        <button onClick={zoomIn} title="Zoom In (+)">+</button>
                        <button onClick={zoomOut} title="Zoom Out (-)">-</button>
                        <button onClick={resetZoom} title="Fit (r)">⟄</button>
                        <button onClick={setActualSize} title="1:1 (a)">1:1</button>
                      </div>
                    </div>
                  )}
                </div>
              );
            }}
          </SwiperSlide>
        ))}
      </Swiper>
    </div>
  );
}
