import { useState } from 'react';
import { useGallery } from '../../context/GalleryContext';
import { PhotoModal } from './PhotoModal';
import styles from './PhotoCard.module.css';

/**
 * Compact photo tile for the gallery grid and cover flow slide.
 * Fulfills REQ-UI-CARD: Interactive photo preview with quick actions.
 * @param {{ photo: import('../../services/idbStorage').PhotoRecord, isCoverFlowMode?: boolean }} props
 */
export function PhotoCard({ photo, isCoverFlowMode = false, panOrigin = '50% 50%' }) {
  const { toggleFavorite, toggleHidden } = useGallery();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isHiding, setIsHiding] = useState(false);

  const handleCardClick = () => setIsModalOpen(true);

  const handleToggleHide = (e) => {
    e.stopPropagation();
    setIsHiding(true);
    setTimeout(() => toggleHidden(photo.id), 300);
  };

  return (
    <>
      <div
        className={`${styles.card} ${photo.is_hidden ? styles.hidden : ''} ${isHiding ? styles.hiding : ''} ${isCoverFlowMode ? styles.coverFlowCard : ''}`}
        onClick={handleCardClick}
        role="button"
        aria-label="Open photo details"
        tabIndex={0}
        onKeyDown={e => e.key === 'Enter' && handleCardClick()}
        data-testid={`photo-card-${photo.id}`}
      >
        <img
          src={photo.url}
          alt="Gallery thumbnail"
          loading="lazy"
          decoding="async"
          className={`${styles.image} ${isCoverFlowMode ? styles.contain : ''}`}
          style={{ objectPosition: isCoverFlowMode ? panOrigin : undefined }}
          onError={e => { e.currentTarget.src = '/placeholder.svg'; }} // graceful broken-image fallback
        />
        {!isCoverFlowMode && (
          <div className={styles.overlay}>
            <button
              onClick={e => { e.stopPropagation(); toggleFavorite(photo.id); }}
              aria-label={photo.is_favorite ? 'Remove from favorites' : 'Add to favorites'}
              className={styles.iconBtn}
            >
              {photo.is_favorite ? '★' : '☆'}
            </button>
            <button
              onClick={handleToggleHide}
              aria-label={photo.is_hidden ? 'Unhide photo' : 'Hide photo'}
              className={styles.iconBtn}
            >
              {photo.is_hidden ? '👁️' : '🚫'}
            </button>
          </div>
        )}
        {photo.tags && photo.tags.length > 0 && (
          <div className={styles.tagRow}>
            {photo.tags.slice(0, 3).map(t => (
              <span key={t} className={styles.tag}>{t}</span>
            ))}
          </div>
        )}
      </div>
      {isModalOpen && (
        <PhotoModal photo={photo} onClose={() => setIsModalOpen(false)} />
      )}
    </>
  );
}
