import { useState } from 'react';
import { useGallery } from '../../context/GalleryContext';
import { useToast } from '../../context/ToastContext';
import { addPhotos, importFromJson, getAllPhotos } from '../../services/idbStorage';
import { parseUrlList, parseJsonBackup, downloadJsonExport } from '../../utils/importExport';
import styles from './ImportModal.module.css';

/**
 * Modal for importing photo URLs from a text file or restoring a JSON backup.
 * Dispatches to context and delegates DB writes to StorageService.
 * Fulfills REQ-UI-IMPORT: User-facing import interface.
 * @param {{ onClose: () => void }} props
 */
export function ImportModal({ onClose }) {
  const { dispatch, photos } = useGallery();
  const { addToast } = useToast();
  const [status, setStatus] = useState(null);
  const [mode, setMode] = useState('text'); // 'text' | 'paste' | 'json'
  const [isLoading, setIsLoading] = useState(false);
  const [pastedText, setPastedText] = useState('');

  const processUrlText = async (rawText) => {
    setIsLoading(true);
    setStatus(null);

    try {
      const { valid, skipped } = parseUrlList(rawText);

      if (valid.length === 0 && skipped === 0) {
        setStatus('No URLs found to import.');
        setIsLoading(false);
        return;
      }

      if (valid.length >= 1000) {
        let totalInserted = 0;
        const CHUNK_SIZE = 250;

        const processChunk = async (index) => {
          if (index >= valid.length) {
            try {
              const newRecords = await getAllPhotos();
              dispatch({ type: 'SET_PHOTOS', payload: newRecords });
              const msg = `Imported ${totalInserted} photos. Skipped ${skipped} invalid lines.`;
              setStatus(msg);
              addToast(msg, 'info');
            } catch (err) {
              const msg = `Import failed: ${err instanceof Error ? err.message : 'Unknown error'}`;
              setStatus(msg);
              addToast(msg, 'error');
            }
            setIsLoading(false);
            return;
          }

          const chunk = valid.slice(index, index + CHUNK_SIZE);
          try {
            const inserted = await addPhotos(chunk);
            totalInserted += inserted;
            setStatus(`Importing... ${Math.min(index + chunk.length, valid.length)} / ${valid.length}`);
            requestAnimationFrame(() => processChunk(index + CHUNK_SIZE));
          } catch (err) {
            const msg = `Import failed: ${err instanceof Error ? err.message : 'Unknown error'}`;
            setStatus(msg);
            addToast(msg, 'error');
            setIsLoading(false);
          }
        };

        processChunk(0);
      } else {
        const inserted = await addPhotos(valid);
        const newRecords = await getAllPhotos();
        dispatch({ type: 'SET_PHOTOS', payload: newRecords });
        const msg = `Imported ${inserted} photos. Skipped ${skipped} invalid lines.`;
        setStatus(msg);
        addToast(msg, 'info');
        setIsLoading(false);
      }
    } catch (err) {
      const msg = `Import failed: ${err instanceof Error ? err.message : 'Unknown error'}`;
      setStatus(msg);
      addToast(msg, 'error');
      setIsLoading(false);
    }
  };

  const handleFileImport = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const rawText = await file.text();

    if (mode === 'text') {
      await processUrlText(rawText);
      e.target.value = '';
    } else if (mode === 'json') {
      setIsLoading(true);
      try {
        // JSON restore is destructive — require confirmation per spec
        if (!window.confirm('This will replace ALL existing gallery data. Continue?')) {
          setIsLoading(false);
          e.target.value = '';
          return;
        }
        const records = parseJsonBackup(rawText);
        await importFromJson(records); // clears and rewrites the IDB store
        dispatch({ type: 'SET_PHOTOS', payload: records });
        const msg = `Restored ${records.length} photos from backup.`;
        setStatus(msg);
        addToast(msg, 'info');
      } catch (err) {
        const msg = `Import failed: ${err instanceof Error ? err.message : 'Unknown error'}`;
        setStatus(msg);
        addToast(msg, 'error');
      }
      setIsLoading(false);
      e.target.value = '';
    }
  };

  const handlePasteSubmit = async () => {
    if (!pastedText.trim()) {
      addToast('Please paste some URLs first.', 'warning');
      return;
    }
    await processUrlText(pastedText);
    setPastedText('');
  };

  const handleExport = () => {
    try {
      downloadJsonExport(photos);
      addToast('Export downloaded successfully.', 'info');
    } catch (err) {
      addToast('Export failed. Please try again.', 'error');
    }
  };

  return (
    <dialog open className={styles.dialog} aria-modal="true" aria-labelledby="import-modal-title">
      <h2 id="import-modal-title">Import / Export Photos</h2>

      <section className={styles.exportSection}>
        <h3>Export</h3>
        <p>Download all gallery data as a JSON backup file.</p>
        <button
          onClick={handleExport}
          className={styles.exportBtn}
          disabled={photos.length === 0}
        >
          Export JSON Backup
        </button>
      </section>

      <hr className={styles.divider} />

      <section className={styles.importSection}>
        <h3>Import</h3>
        <div className={styles.modeToggle} role="group" aria-label="Import mode">
          <button
            id="mode-text"
            onClick={() => setMode('text')}
            className={mode === 'text' ? styles.active : ''}
            aria-pressed={mode === 'text'}
          >
            Text File
          </button>
          <button
            id="mode-paste"
            onClick={() => setMode('paste')}
            className={mode === 'paste' ? styles.active : ''}
            aria-pressed={mode === 'paste'}
          >
            Paste URLs
          </button>
          <button
            id="mode-json"
            onClick={() => setMode('json')}
            className={mode === 'json' ? styles.active : ''}
            aria-pressed={mode === 'json'}
          >
            JSON Backup
          </button>
        </div>
        <p>
          {mode === 'text' && 'Upload a .txt file with one image URL per line.'}
          {mode === 'paste' && 'Paste a list of image URLs (one per line) directly into the box below.'}
          {mode === 'json' && 'Upload a previously exported .json backup file. This will REPLACE all current data.'}
        </p>

        {mode === 'paste' ? (
          <div className={styles.pasteContainer}>
            <textarea
              className={styles.textArea}
              placeholder="https://example.com/image1.jpg&#10;https://example.com/image2.jpg"
              value={pastedText}
              onChange={(e) => setPastedText(e.target.value)}
              disabled={isLoading}
            />
            <button
              onClick={handlePasteSubmit}
              className={styles.submitPasteBtn}
              disabled={isLoading || !pastedText.trim()}
            >
              Import Pasted URLs
            </button>
          </div>
        ) : (
          <input
            id="file-import-input"
            type="file"
            accept={mode === 'text' ? '.txt' : '.json'}
            onChange={handleFileImport}
            disabled={isLoading}
            className={styles.fileInput}
          />
        )}
        {isLoading && <p className={styles.loadingMsg}>Importing, please wait…</p>}
        {status && <p className={styles.statusMsg}>{status}</p>}
      </section>

      <button onClick={onClose} className={styles.closeBtn} aria-label="Close import modal">
        Close
      </button>
    </dialog>
  );
}
